new='''            render_player_takes_fragment(sim_players, portfolio, contest_results, portfolio_stats, manage_size, manage_overlap, manage_player, manage_qb, manage_path, manage_team, manage_game)\n\n'''
if old not in s:
    raise SystemExit('Player Takes block not found')
s=s.replace(old,new,1)
p.write_text(s,encoding='utf-8')
